def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_d = 0
    for me, op in history:
        if op == 'D':
            opp_d += 1
    opp_c = n - opp_d
    last_me, last_opp = history[-1]

    recent = history[-min(12, n):]
    rd = sum(1 for _, op in recent if op == 'D')
    recent5 = history[-min(5, n):]
    rd5 = sum(1 for _, op in recent5 if op == 'D')

    streak = 0
    for _, op in reversed(history):
        if op == 'D':
            streak += 1
        else:
            break

    if opp_c == 0 or (n >= 12 and opp_d * 3 >= n * 2 and rd >= 4):
        return 'D'

    if last_opp == 'D':
        if streak >= 6 or (streak >= 4 and opp_d * 2 >= n):
            return 'D'

        if last_me == 'D':
            if opp_d * 2 < n and streak <= 2:
                return 'C'
            if opp_d * 2 < n and rng.random() < 0.4:
                return 'C'
            return 'D'

        if n >= 2 and history[-2][0] == 'D':
            if opp_d * 3 < n * 2 and streak <= 2:
                return 'C'
            if opp_d * 2 < n and rng.random() < 0.5:
                return 'C'
            return 'D'

        if opp_d <= 1 and opp_c * 10 >= n * 9 and streak == 1 and rd5 <= 1:
            return 'C'
        if opp_d <= 2 and opp_c * 5 >= n * 4 and streak <= 1 and rd5 <= 2:
            if rng.random() < 0.6:
                return 'C'
        return 'D'

    unret = 0
    pun = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                unret += 1
            else:
                pun += 1

    exploit = False

    if opp_c == n and n >= 22:
        exploit = True

    if unret >= 5 and pun == 0 and opp_d <= 1 and rd <= 1 and opp_c * 10 >= n * 9:
        exploit = True

    if unret >= 8 and pun <= 1 and opp_d <= 2 and rd <= 2 and rd5 == 0:
        exploit = True

    if exploit:
        if last_me == 'D' and unret == 0 and pun == 0:
            return 'C'
        if n >= 60 and pun > 0 and last_me == 'C' and rng.random() < 0.12:
            return 'C'
        return 'D'

    if last_me == 'D':
        return 'C'

    if rd >= 5 and rd5 >= 3:
        return 'D'

    if n > 85 and opp_d * 2 > n:
        return 'D'

    return 'C'
